fn main() {
    if std::env::var("DOCS_RS").is_ok() {
        return;
    }

    #[cfg(feature = "sys")]
    sys::build_ffi();
}

#[cfg(feature = "sys")]
mod sys {
    use std::{
        env, fs, os,
        path::{Path, PathBuf},
    };

    use pathdiff::diff_paths;

    /// The library name, used for the static library archive and the headers.
    /// Should be chosen as to not conflict with other library/header names.
    const LIB_NAME: &str = "dt-recursion-core-sys";

    /// The name of all include directories involved, used to find and output header files.
    const INCLUDE_DIRNAME: &str = "include";

    /// The name of the directory to recursively search for source files in.
    const SOURCE_DIRNAME: &str = "cpp";

    /// The warning placed in the cbindgen header.
    const AUTOGEN_WARNING: &str =
        "/* Automatically generated by `cbindgen`. Not intended for manual editing. */";

    fn feature_enabled(feature: &str) -> bool {
        let env_key = format!("CARGO_FEATURE_{}", feature.replace('-', "_").to_ascii_uppercase());
        env::var_os(env_key).is_some()
    }

    /// Active `Block<T>` storage width: quintic ext5 = 5, default quartic ext4 = 4.
    fn active_block_width() -> &'static str {
        if feature_enabled("ext5") {
            "5"
        } else {
            "4"
        }
    }

    /// Field-driven Poseidon2 constants `(num_internal_rounds, sbox_degree)`:
    /// BabyBear = (13, 7), KoalaBear = (20, 3).
    fn active_poseidon_constants() -> (&'static str, &'static str) {
        if feature_enabled("babybear") {
            ("13", "7")
        } else {
            ("20", "3")
        }
    }

    pub fn build_ffi() {
        // The name of the header generated by `cbindgen`.
        let cbindgen_hpp = &format!("{LIB_NAME}-cbindgen.hpp");

        // The crate directory.
        let crate_dir = PathBuf::from(env::var("CARGO_MANIFEST_DIR").unwrap());

        // The output directory, where built artifacts should be placed.
        let out_dir = PathBuf::from(env::var("OUT_DIR").unwrap());

        // The target directory that the cargo invocation is using.
        // Headers are symlinked into `target/include` purely for IDE purposes.
        let target_dir = {
            let mut dir = out_dir.clone();
            loop {
                if dir.ends_with("target") {
                    break dir;
                }
                if !dir.pop() {
                    panic!("OUT_DIR does not have parent called \"target\": {out_dir:?}");
                }
            }
        };

        // The directory to read headers from.
        let source_include_dir = crate_dir.join(INCLUDE_DIRNAME);

        // The directory to place headers into.
        let target_include_dir = out_dir.join(INCLUDE_DIRNAME);

        // The directory to place symlinks to headers into. Has the fixed path "target/include".
        let target_include_dir_fixed = target_dir.join(INCLUDE_DIRNAME);

        // The directory to read source files from.
        let source_dir = crate_dir.join(SOURCE_DIRNAME);

        let headers = glob::glob(source_include_dir.join("**/*.hpp").to_str().unwrap())
            .unwrap()
            .collect::<Result<Vec<_>, _>>()
            .unwrap();

        let compilation_units = glob::glob(source_dir.join("**/*.cpp").to_str().unwrap())
            .unwrap()
            .collect::<Result<Vec<_>, _>>()
            .unwrap();

        // Tell Cargo that if the given file changes, to rerun this build script.
        println!("cargo::rerun-if-changed={INCLUDE_DIRNAME}");
        println!("cargo::rerun-if-changed={SOURCE_DIRNAME}");
        println!("cargo::rerun-if-changed=src");
        println!("cargo::rerun-if-changed=Cargo.toml");

        // Cargo build script metadata, used by dependents' build scripts.
        // The root directory containing the library archive.
        println!("cargo::metadata=root={}", out_dir.to_str().unwrap());

        // The include path defining the library's API.
        println!("cargo::metadata=include={}", target_include_dir.to_str().unwrap());

        // Generate a header containing bindings to the crate.
        match cbindgen::Builder::new()
            .with_pragma_once(true)
            .with_autogen_warning(AUTOGEN_WARNING)
            .with_no_includes()
            .with_sys_include("cstdint")
            .with_sys_include("cstddef")
            .with_parse_deps(true)
            .with_parse_include(&[
                "dt-stark",
                "dt-primitives",
                "dt-core-machine",
                "p3-baby-bear",
                "dt-core-executor",
            ])
            .with_parse_extra_bindings(&["dt-stark", "dt-primitives", "p3-baby-bear"])
            .rename_item("BabyBear", "BabyBearP3")
            .include_item("BaseAluEvent")
            .include_item("BaseAluValueCols")
            .include_item("BaseAluAccessCols")
            .include_item("BaseAluInstr")
            .include_item("ExtAluEvent")
            .include_item("ExtAluValueCols")
            .include_item("ExtAluInstr")
            .include_item("ExtAluAccessCols")
            .include_item("BatchFRIEvent")
            .include_item("BatchFRICols")
            .include_item("BatchFRIInstrFFI")
            .include_item("BatchFRIPreprocessedCols")
            .include_item("ExpReverseBitsEventFFI")
            .include_item("ExpReverseBitsLenCols")
            .include_item("ExpReverseBitsInstrFFI")
            .include_item("ExpReverseBitsLenPreprocessedCols")
            .include_item("FriFoldEvent")
            .include_item("FriFoldCols")
            .include_item("FriFoldInstrFFI")
            .include_item("FriFoldPreprocessedCols")
            .include_item("SelectEvent")
            .include_item("SelectCols")
            .include_item("CommitPublicValuesEvent")
            .include_item("PublicValuesCols")
            .include_item("CommitPublicValuesInstr")
            .include_item("PublicValuesPreprocessedCols")
            .include_item("SelectEvent")
            .include_item("SelectCols")
            .include_item("SelectInstr")
            .include_item("SelectPreprocessedCols")
            .include_item("Poseidon2Event")
            .include_item("Poseidon2")
            .include_item("Poseidon2Instr")
            .include_item("Poseidon2WideInstr")
            .include_item("Poseidon2PreprocessedColsSkinny")
            .include_item("Poseidon2PreprocessedColsWide")
            .include_item("PolyEvalEventFFI")
            .include_item("PolyEvalCols")
            .include_item("PolyEvalInstrFFI")
            .include_item("PolyEvalPreprocessedCols")
            .include_item("ExtPolyEvalEventFFI")
            .include_item("ExtPolyEvalCols")
            .include_item("ExtPolyEvalInstrFFI")
            .include_item("ExtPolyEvalPreprocessedCols")
            .include_item("ExtExpReverseBitsEventFFI")
            .include_item("ExtExpReverseBitsLenCols")
            .include_item("ExtExpReverseBitsInstrFFI")
            .include_item("ExtExpReverseBitsLenPreprocessedCols")
            .include_item("ExtDotProdEventFFI")
            .include_item("ExtDotProdLenCols")
            .include_item("ExtDotProdInstrFFI")
            .include_item("ExtDotProdPreprocessedCols")
            .include_item("ExtDotProdBaseEventFFI")
            .include_item("ExtDotProdBaseCols")
            .include_item("ExtDotProdBaseInstrFFI")
            .include_item("ExtDotProdBasePreprocessedCols")
            .with_namespace("dt_recursion_core_sys")
            .with_crate(crate_dir)
            .generate()
        {
            Ok(bindings) => {
                // Write the bindings to the target include directory.
                // We always write and post-process, rather than relying on
                // `write_to_file`'s return value (which skips when content is unchanged,
                // causing the post-processing to be skipped on cached builds).
                let header_path = target_include_dir.join(cbindgen_hpp);
                let mut header_content = Vec::new();
                bindings.write(&mut header_content);
                if let Some(parent) = header_path.parent() {
                    fs::create_dir_all(parent).unwrap();
                }
                fs::write(&header_path, &header_content).unwrap();

                // Post-process the generated header to remove duplicate constant
                // definitions caused by cbindgen not understanding #[cfg] attributes.
                // When both `koalabear` and default (babybear) variants of a constant
                // exist, cbindgen emits both, causing C++ redefinition errors.
                // We keep only the variant matching the active feature.
                deduplicate_cbindgen_constants(&header_path);

                // Symlink the header to the fixed include directory.
                rel_symlink_file(header_path, target_include_dir_fixed.join(cbindgen_hpp));
            }
            Err(cbindgen::Error::ParseSyntaxError { .. }) => {} /* Ignore parse errors so */
            // rust-analyzer can run.
            Err(e) => panic!("{e:?}"),
        }

        // Copy the headers to the include directory and symlink them to the fixed include
        // directory.
        for header in &headers {
            // Get the path of the header relative to the source include directory.
            let relpath = diff_paths(header, &source_include_dir).unwrap();

            // Let the destination path be the same place relative to the target include directory.
            let dst = target_include_dir.join(&relpath);

            // Create the parent directory if it does not exist.
            if let Some(parent) = dst.parent() {
                fs::create_dir_all(parent).unwrap();
            }
            fs::copy(header, &dst).unwrap();
            rel_symlink_file(dst, target_include_dir_fixed.join(relpath));
        }

        println!("cargo::rustc-link-lib=static=dt-core-machine-sys");
        let include_dir = env::var("DEP_DT_CORE_MACHINE_SYS_INCLUDE").unwrap();

        // Use the `cc` crate to build the library and statically link it to the crate.
        let mut cc_builder = cc::Build::new();
        cc_builder.files(&compilation_units).include(target_include_dir).include(include_dir);
        cc_builder.cpp(true).std("c++17");
        // Keep the C++ field selection aligned with the Rust feature set. This
        // also enables the ABI-only BabyBear wrapper used by KoalaBear FFI.
        if cfg!(feature = "koalabear") {
            cc_builder.define("USE_KOALABEAR", None);
        }
        cc_builder.compile(LIB_NAME)
    }

    /// Post-process the cbindgen-generated header to handle feature-dependent constants.
    ///
    /// cbindgen does not understand `#[cfg]` attributes. Constants marked with
    /// `/// cbindgen:ignore` are not emitted, while those without the annotation but
    /// with cfg-gated duplicates are emitted twice. This function:
    /// 1. Removes any duplicate definitions (keeps only the active-feature value).
    /// 2. Injects constants that were excluded by `cbindgen:ignore` but are still needed by C++
    ///    code, right after the `NUM_EXTERNAL_ROUNDS` definition so they are available before any
    ///    struct or function that uses them.
    fn deduplicate_cbindgen_constants(header_path: &Path) {
        let mut content = fs::read_to_string(header_path).unwrap();
        // cbindgen cannot resolve the `#[cfg]`-gated `D` constant, so rewrite the
        // `Block<T>` storage `T _0[D]` to the active concrete width here.
        content = content.replace("_0[D]", &format!("_0[{}]", active_block_width()));
        let lines: Vec<&str> = content.lines().collect();

        // Determine the correct values based on the active field feature.
        let (num_internal_rounds, sbox_degree) = active_poseidon_constants();

        let constants_to_inject = format!(
            "\nconstexpr static const uintptr_t NUM_INTERNAL_ROUNDS = {num_internal_rounds};\n\
             \nconstexpr static const uintptr_t NUM_ROUNDS = (NUM_EXTERNAL_ROUNDS + NUM_INTERNAL_ROUNDS);\n\
             \nconstexpr static const uintptr_t NUM_INTERNAL_ROUNDS_S0 = (NUM_INTERNAL_ROUNDS - 1);\n\
             \nconstexpr static const uint64_t POSEIDON2_SBOX_DEGREE = {sbox_degree};\n",
        );

        // Patterns for lines that should be deduplicated (wrong-value removed).
        let dedup_patterns: &[(&str, &str)] =
            &[("NUM_INTERNAL_ROUNDS", num_internal_rounds), ("POSEIDON2_SBOX_DEGREE", sbox_degree)];

        let mut result_lines: Vec<String> = Vec::with_capacity(lines.len() + 8);
        let mut injected = false;

        for line in &lines {
            let trimmed = line.trim();

            // Remove duplicate definitions with the wrong value.
            let mut should_remove = false;
            for &(const_name, keep_val) in dedup_patterns {
                let pattern = format!(" {const_name} =");
                if trimmed.starts_with("constexpr") && trimmed.contains(&pattern) {
                    let has_correct_value = trimmed.contains(&format!("= {keep_val};")) ||
                        trimmed.contains(&format!("= {keep_val});"));
                    if !has_correct_value {
                        should_remove = true;
                    }
                }
            }
            if should_remove {
                continue;
            }

            result_lines.push(line.to_string());

            // Inject the feature-dependent constants right after NUM_EXTERNAL_ROUNDS.
            // This ensures they are defined before any struct or function uses them.
            if !injected &&
                trimmed.starts_with("constexpr") &&
                trimmed.contains(" NUM_EXTERNAL_ROUNDS =")
            {
                result_lines.push(constants_to_inject.clone());
                injected = true;
            }
        }

        // Fallback: if NUM_EXTERNAL_ROUNDS was not found, inject before closing `}`.
        if !injected {
            let closing_brace_idx = result_lines.iter().rposition(|l| l.trim() == "}");
            if let Some(idx) = closing_brace_idx {
                result_lines.insert(idx, constants_to_inject);
            } else {
                result_lines.push(constants_to_inject);
            }
        }

        let new_content = result_lines.join("\n") + "\n";
        fs::write(header_path, new_content).unwrap();
    }

    /// Place a relative symlink pointing to `original` at `link`.
    fn rel_symlink_file<P, Q>(original: P, link: Q)
    where
        P: AsRef<Path>,
        Q: AsRef<Path>,
    {
        #[cfg(unix)]
        use os::unix::fs::symlink;
        #[cfg(windows)]
        use os::windows::fs::symlink_file as symlink;

        let target_dir = link.as_ref().parent().unwrap();
        fs::create_dir_all(target_dir).unwrap();
        let _ = fs::remove_file(&link);
        let relpath = diff_paths(original, target_dir).unwrap();
        symlink(relpath, link).unwrap();
    }
}
